# Each day: t title, f format, p parts ({q} placeholders), q list of (quote, ref), img subject or None
P="Proverb of the Week"; S="Story in 60 Seconds"; M="What It Really Means"; J="Words of Jesus"; MT="Myth vs. Truth"; Q="Your Turn (Question)"; R="Sunday Rest (Psalm)"; T="Thread"
D=[
# Week 1 – famous verses to win followers
dict(s=P,t="Gentle answers win",f="Hook + insight + life application",p=["Someone snaps at you. You want to snap back.\n\n3,000-year-old advice:\n\n\"{q}\"\n— Proverbs 15:1\n\nSoft is not weak. Soft is strategic. Try it once today and watch what happens."],q=[("A gentle answer turns away anger, but a harsh word stirs up anger.","Sprueche:15:1")],img="two speech bubbles, one jagged and one smooth and glowing, the smooth one calming the jagged one"),
dict(s=S,t="David vs. Goliath",f="Thread (mini-story retelling)",p=["1/ A teenage shepherd. A trained giant in armor. Everyone expected a massacre.\n\nThe story of David and Goliath in 60 seconds 🧵","2/ The whole army was frozen with fear. For 40 days the giant mocked them. Nobody moved.\n\nThen David, too young to be a soldier, said: I'll go.","3/ No armor. No sword. Just a sling and five smooth stones.\n\n\"{q}\"\n— 1 Samuel 17:49","4/ The point is not ‘you can beat every giant.’\n\nThe point: courage starts when you stop measuring the giant and start trusting the God who is bigger.\n\nWhat's your giant right now?"],q=[("David put his hand into his bag, took out a stone, slung it, and struck the Philistine on his forehead.","1-Samuel:17:49")],img="a small shepherd silhouette with a sling facing a towering shadow of a giant, a single gold stone glowing mid-air"),
dict(s=M,t="John 3:16, simply",f="What this really means",p=["The most famous verse in the world, in plain words:\n\n\"{q}\"\n— John 3:16\n\nNot just the good people.\nThe world. That includes you, on your worst day."],q=[("God loved the world very much. So he gave his only born Son. Everyone who believes in him will not be lost. They will have eternal life.","Johannes:3:16")],img="a glowing gold line-art globe held gently by two open hands of light"),
dict(s=J,t="Don't worry about tomorrow",f="Hook + insight + life application",p=["Your brain is living in next week. Jesus pulls it back to today:\n\n\"{q}\"\n— Matthew 6:34\n\nYou got strength for today, not for next month all at once."],q=[("So don’t worry about tomorrow, for tomorrow will worry about itself. Each day has enough trouble of its own.","Matthaeus:6:34")],img=None),
dict(s=MT,t="Myth: faith means no doubts",f="Myth vs. truth",p=["Myth: Real faith means you never doubt.\n\nTruth: Peter walked on water, looked at the wind, and started sinking.\n\n\"{q}\"\n— Matthew 14:31\n\nJesus didn't let him drown for doubting. He grabbed his hand."],q=[("At once Jesus stretched out his hand, took hold of him","Matthaeus:14:31")],img="a hand of gold light reaching down to grab a hand rising from dark stormy waves"),
dict(s=Q,t="Which verse got you through?",f="Question to drive replies",p=["Honest question:\n\nIs there one Bible verse that got you through a hard season?\n\nDrop it below 👇 Someone scrolling tonight might need exactly that verse."],q=[],img=None),
dict(s=R,t="Psalm 23: The Lord is my shepherd",f="Psalm reflection + soft CTA",p=["Psalm 23, in clear words:\n\n\"{q}\"\n\nA good shepherd leads tired sheep to rest.\n\nThe whole Bible like this, every verse in plain words: link in bio."],q=[("The LORD is my shepherd. I will not lack anything. He lets me lie down in green pastures. He leads me beside still waters.","Psalmen:23:1-2")],img="a calm shepherd's crook in gold line art beside still water under a midnight sky, warm soft light"),
# Week 2
dict(s=P,t="Trust over overthinking",f="Hook + insight + life application",p=["For the overthinkers:\n\n\"{q}\"\n— Proverbs 3:5–6\n\nYou don't need to see the whole road. Just the next step."],q=[("Trust in the LORD with all your heart. Don’t depend on your own understanding. Think of him in everything you do. Then he will make your paths straight.","Sprueche:3:5-6")],img="a winding path in gold line art turning into a straight glowing road toward a sunrise"),
dict(s=S,t="Noah and the rainbow",f="Thread (mini-story retelling)",p=["1/ Everyone knows the ark. Few remember how the story ends 🧵","2/ After the flood, Noah steps onto a wet, empty world. Everything he knew is gone.\n\nAnd God makes a promise, with something you still see today.","3/ \"{q}\"\n— Genesis 9:13","4/ Next time you see a rainbow after a storm, remember: the Bible's first big \"never again\" is a promise of mercy.\n\nStorms end. Promises stay."],q=[("I set my rainbow in the clouds. It will be the sign of the covenant between me and the earth.","1-Mose:9:13")],img="a gold line-art rainbow arching over a small ark resting on a mountain, storm clouds parting into midnight blue"),
dict(s=M,t="'I can do all things'",f="What this really means",p=["\"{q}\" — Philippians 4:13\n\nOften used for sports and exams. But Paul wrote it from prison, about being content with little OR much.\n\nIt's not ‘I can win everything.’\nIt's ‘I can get through anything.’"],q=[("I can do all things through Christ who strengthens me.","Philipper:4:13")],img=None),
dict(s=J,t="Come to me, you who are tired",f="Hook + insight + life application",p=["If you're exhausted today, this is for you:\n\n\"{q}\"\n— Matthew 11:28\n\nNot ‘try harder.’ Not ‘earn it.’\n\nRest is an invitation, not a reward."],q=[("“Come to me, all you who are weary and heavily burdened, and I will give you rest.","Matthaeus:11:28")],img="an open wooden door in gold line art with warm light spilling out into a dark blue night"),
dict(s=T,t="5 verses for anxiety",f="Thread",p=["1/ 5 Bible verses for anxious days. Save this one 🧵","2/ \"{q0}\"\n— 1 Peter 5:7","3/ \"{q1}\"\n— Psalm 56:3","4/ \"{q2}\"\n— Isaiah 41:10","5/ \"{q3}\"\n— John 14:27\n\nWhich one do you need most today?"],q=[("Cast all your worries on him, because he cares for you.","1-Petrus:5:7"),("When I am afraid, I will put my trust in you.","Psalmen:56:3"),("Do not be afraid, for I am with you. Do not be discouraged, for I am your God. I will strengthen you.","Jesaja:41:10"),("I leave peace with you. I give you my peace. I don’t give it to you the way the world gives. Don’t let your heart be upset or afraid.","Johannes:14:27")],img="five small gold stars forming a gentle arc over a calm midnight lake"),
dict(s=Q,t="Fill in the blank: love is…",f="Question to drive replies",p=["1 Corinthians 13 says love is patient, love is kind…\n\nFinish the sentence from your own life:\n\n‘Love is ______.’\n\nBest answers get shared next week 👇"],q=[],img=None),
dict(s=R,t="Be still",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 46:10\n\nNot ‘be busy and know.’\nNot ‘be perfect and know.’\n\nBe still. Phone down for 2 minutes today.\n\nThe Bible in plain words, every verse explained: link in bio."],q=[("“Be still, and know that I am God.","Psalmen:46:10")],img="a single gold line of a horizon over perfectly still water reflecting stars"),
# Week 3 – fear & courage
dict(s=P,t="Words have power",f="Hook + insight + life application",p=["Before you post that comment:\n\n\"{q}\"\n— Proverbs 18:21\n\nYour words can build someone up for a week or knock them down for a year.\n\nUse yours to give life today."],q=[("Death and life are in the power of the tongue.","Sprueche:18:21")],img=None),
dict(s=S,t="Moses and the Red Sea",f="Thread (mini-story retelling)",p=["1/ An army behind them. A sea in front of them. No way out.\n\nThe Red Sea in 60 seconds 🧵","2/ The people panic and blame Moses. Moses says something surprising:\n\n\"{q0}\"\n— Exodus 14:14","3/ \"{q1}\"\n— Exodus 14:21","4/ Sometimes the way forward doesn't exist yet when you start walking.\n\nStand still. Then step."],q=[("The LORD will fight for you. And you must be still.”","2-Mose:14:14"),("Moses reached out his hand over the sea. Then the LORD drove the sea back with a strong east wind all night. He made the sea into dry land.","2-Mose:14:21")],img="a path between two towering walls of water drawn in gold line art, light shining at the far end"),
dict(s=M,t="Joshua 1:9",f="What this really means",p=["\"{q}\"\n— Joshua 1:9\n\nReplacing Moses, Joshua was scared. God didn't say ‘you're ready.’ He said ‘I'm with you.’\n\nCourage = knowing you're not alone."],q=[("Be strong and courageous! Don’t be afraid. Don’t lose heart, for the LORD your God is with you wherever you go.”","Josua:1:9")],img="a lone figure at the edge of a river looking at a promised land, gold line art, dawn light"),
dict(s=J,t="Don't be afraid, only believe",f="Hook + insight + life application",p=["A father just got the worst news possible. Jesus turns to him and says five words:\n\n\"{q}\"\n— Mark 5:36\n\nWhen the news is bad, faith doesn't deny it. Faith holds on anyway."],q=[("“Don’t be afraid, only believe.”","Markus:5:36")],img=None),
dict(s=MT,t="Myth: God gave us fear",f="Myth vs. truth",p=["Myth: Fear is just how God made you.\n\nTruth:\n\"{q}\"\n— 2 Timothy 1:7\n\nFear will visit. It just doesn't get to drive."],q=[("For God didn’t give us a spirit of fear, but of power, love and self-control.","2-Timotheus:1:7")],img="a gold lion line icon resting calmly beside a small flame, midnight blue"),
dict(s=Q,t="What are you afraid of?",f="Question to drive replies",p=["Isaiah 43:2 says: when you pass through the waters, God is with you.\n\nNot \"if.\" When.\n\nWhat \"waters\" are you walking through this month? Reply or just ❤️ if you'd like people to pray for you."],q=[],img=None),
dict(s=R,t="Joy comes in the morning",f="Psalm reflection + soft CTA",p=["For anyone who cried last night:\n\n\"{q}\"\n— Psalm 30:5\n\nNights end. Morning comes.\n\nWe explain every psalm in simple words. Link in bio if you want to read more."],q=[("Weeping may stay for the night, but joy comes in the morning.","Psalmen:30:5")],img="first golden rays of sunrise breaking over dark blue hills, a single gold line-art sun"),
# Week 4
dict(s=P,t="Iron sharpens iron",f="Hook + insight + life application",p=["Show me your 5 closest friends and I'll show you your future.\n\n\"{q}\"\n— Proverbs 27:17\n\nThe right people don't just make you comfortable. They make you sharper.\n\nTag someone who sharpens you."],q=[("Iron sharpens iron, so a person sharpens his friend’s face.","Sprueche:27:17")],img="two gold line-art blades crossing with small sparks of light"),
dict(s=S,t="Joseph: from pit to palace",f="Thread (mini-story retelling)",p=["1/ Betrayed by his brothers. Sold as a slave. Thrown in prison for something he didn't do.\n\nJoseph's story in 60 seconds 🧵","2/ Years later, Joseph is second in command of Egypt. A famine hits. His brothers show up, begging for food. They don't recognize him.","3/ He could take revenge. Instead:\n\n\"{q}\"\n— Genesis 50:20","4/ Your pain is not the end of your story. Sometimes it's the road to the place where you can help the most."],q=[("You planned evil against me. But God planned it for good.","1-Mose:50:20")],img="a colorful robe in gold line art transforming into a royal ring, midnight blue background"),
dict(s=M,t="Jeremiah 29:11",f="What this really means",p=["\"{q}\"\n— Jeremiah 29:11\n\nContext: God said this to people living in exile, far from home, for 70 years.\n\nNot a promise of an easy life. A promise that God hasn't forgotten you, even there."],q=[("thoughts of peace, and not of disaster, to give you hope and a future.","Jeremia:29:11")],img=None),
dict(s=J,t="Love your neighbor as yourself",f="Hook + insight + life application",p=["The most important rule? Jesus gave two:\n\n1. \"{q0}\"\n2. \"{q1}\"\n— Matthew 22:37–39\n\nNotice the last word: yourself. Be kind to you too."],q=[("You shall love the Lord your God with all your heart, with all your soul, and with all your mind.","Matthaeus:22:37"),("You shall love your neighbor as yourself.","Matthaeus:22:39")],img="two gold line hearts linked, one larger above, one beside a small human figure"),
dict(s=T,t="Why read the Bible in plain words?",f="Thread",p=["1/ ‘I tried reading the Bible but I didn't understand anything.’\n\nIf that's you, this thread is for you 🧵","2/ The Bible was written in everyday Hebrew and Greek. Fishermen and farmers understood it.\n\nOld English makes it feel far away. It was never meant to be.","3/ Plain words + a short explanation after each section = you finally get what's going on. Who, where, why it matters.","4/ That's what this account is about. One verse a day, explained simply.\n\nFollow along. Tomorrow's post is a good one."],q=[],img="an open book in gold line art with beams of warm light rising from its pages"),
dict(s=Q,t="Story or verse?",f="Question to drive replies",p=["Quick poll for this account 👇\n\nWhat helps you more?\n\nA) Bible stories retold in 60 seconds\nB) One verse explained simply\nC) Myth vs. truth\nD) Threads on big questions\n\nReply with a letter."],q=[],img=None),
dict(s=R,t="Lamp for my feet",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 119:105\n\nA lamp, not a stadium floodlight. It shows you the next few steps, not the whole road.\n\nThat's enough.\n\nWant to read the Bible in plain words? Link in bio."],q=[("Your word is a lamp for my feet and a light for my path.","Psalmen:119:105")],img="an old oil lamp in gold line art lighting a few stones of a dark path"),
# Week 5 – words & relationships
dict(s=P,t="Quick to listen",f="Hook + insight + life application",p=["The 3-part rule that would fix most arguments online:\n\n\"{q}\"\n— James 1:19\n\nListen fast. Speak slow. Get angry slowest.\n\nMost of us do it in reverse."],q=[("Let every person be quick to hear, slow to speak and slow to anger.","Jakobus:1:19")],img=None),
dict(s=S,t="Ruth: loyalty that changed history",f="Thread (mini-story retelling)",p=["1/ A widow. A foreigner. No money, no future.\n\nRuth's story in 60 seconds 🧵","2/ Her mother-in-law Naomi has lost everything and tells Ruth to go home. Ruth refuses:\n\n\"{q}\"\n— Ruth 1:16","3/ She works in the fields to feed them both. A man named Boaz notices her kindness and protects her. They marry.","4/ Their great-grandson? King David.\n\nOne act of loyalty can echo for generations."],q=[("For where you go, I will go. And where you stay, I will stay. Your people will be my people, and your God will be my God.","Rut:1:16")],img="two women walking together on a road through golden wheat fields, gold line art on midnight blue"),
dict(s=M,t="Love is patient",f="What this really means",p=["You've heard it at weddings. Read it again slowly:\n\n\"{q}\"\n— 1 Corinthians 13:4–5\n\nNow replace ‘love’ with your name. Which line is hardest for you?"],q=[("Love is patient. Love is kind. Love is not jealous. Love does not brag. It is not proud. It is not rude.","1-Korinther:13:4-5")],img="a gold line-art heart made of a single continuous line, soft warm glow"),
dict(s=J,t="Treat others how you want to be treated",f="Hook + insight + life application",p=["The Golden Rule, from the original source:\n\n\"{q}\"\n— Luke 6:31\n\nNot \"how they treat you.\" How you WANT to be treated.\n\nThat changes everything in a group chat."],q=[("Treat other people the way you want them to treat you.","Lukas:6:31")],img=None),
dict(s=MT,t="Myth: Forgive = forget",f="Myth vs. truth",p=["Myth: Forgiving means pretending it didn't happen.\n\nTruth: Peter asked, ‘7 times?’ Jesus said:\n\n\"{q}\"\n— Matthew 18:22\n\nForgiveness isn't amnesia. It's choosing to stop keeping score."],q=[("“I don’t tell you up to 7 times, but up to 70 times 7.","Matthaeus:18:22")],img="a broken chain in gold line art with links falling away into light"),
dict(s=Q,t="Who is your Ruth?",f="Question to drive replies",p=["Proverbs 17:17: a friend loves at all times.\n\nWho stayed with you when it would have been easier to leave?\n\nTag them or tell us about them 👇"],q=[],img=None),
dict(s=R,t="Two are better than one",f="Reflection + soft CTA",p=["\"{q}\"\n— Ecclesiastes 4:9–10\n\nNobody was made to do life alone. Text a friend today.\n\nThe Bible in clear words: link in bio."],q=[("Two are better than one, because they have a good reward for their hard work. For if they fall, the one will help his friend up.","Prediger:4:9-10")],img="two gold line figures, one helping the other stand up, under a starry sky"),
# Week 6
dict(s=P,t="Guard your heart",f="Hook + insight + life application",p=["What you feed your heart shapes your whole life.\n\n\"{q}\"\n— Proverbs 4:23\n\nYour feed is food for your heart. What are you scrolling into it?"],q=[("Guard your heart with all care, for out of it is the spring of life.","Sprueche:4:23")],img="a gold line-art heart with a small spring of water flowing out of it"),
dict(s=S,t="The Good Samaritan",f="Thread (mini-story retelling)",p=["1/ A man is beaten and left half dead on the road. Two religious leaders walk past.\n\nThe third person to stop was the last one anyone expected 🧵","2/ He was a Samaritan, someone the listeners saw as an outsider.","3/ \"{q}\"\n— Luke 10:34","4/ Jesus' question isn't ‘who is my neighbor?’\n\nIt's ‘who will I be a neighbor to?’"],q=[("He went to the man. He poured oil and wine on his wounds and bandaged them. Then he put the man on his own animal.","Lukas:10:34")],img="a traveler kneeling to help a wounded man on a desert road, gold line art, a donkey nearby, warm light"),
dict(s=M,t="Overcome evil with good",f="What this really means",p=["\"{q}\"\n— Romans 12:21\n\nRevenge feels powerful for a minute.\nKindness changes the story.\n\nThis isn't weakness. It's refusing to let someone else's evil turn you into someone you're not."],q=[("Don’t be overcome by evil, but overcome evil with good.","Roemer:12:21")],img=None),
dict(s=J,t="Throw the first stone",f="Hook + insight + life application",p=["A crowd holds stones. A woman waits to die. Jesus writes in the dust and says:\n\n\"{q}\"\n— John 8:7\n\nOne by one, they drop their stones.\n\nBefore we judge, we look in the mirror."],q=[("“Whoever among you has never sinned may throw the first stone at her.”","Johannes:8:7")],img="stones dropped on dusty ground with writing in the sand, gold line art, soft light"),
dict(s=T,t="5 Proverbs about friends",f="Thread",p=["1/ 5 Proverbs about friendship that still hit 3,000 years later 🧵","2/ \"{q0}\"\n— Proverbs 17:17","3/ \"{q1}\"\n— Proverbs 13:20","4/ \"{q2}\"\n— Proverbs 10:12","5/ \"{q3}\"\n— Proverbs 12:25\n\nWhich friend needs that kind word today?"],q=[("A friend loves at all times, and a brother is born for times of trouble.","Sprueche:17:17"),("Whoever walks with wise people becomes wise, but whoever makes friends with fools will be harmed.","Sprueche:13:20"),("Hatred stirs up quarrels, but love covers all wrongs.","Sprueche:10:12"),("Worry in a person’s heart weighs it down, but a kind word makes it glad.","Sprueche:12:25")],img=None),
dict(s=Q,t="Kindest words you ever got",f="Question to drive replies",p=["Proverbs 25:11 says a word at the right time is like apples of gold.\n\nWhat's the kindest thing someone ever said to you, right when you needed it? 👇"],q=[],img=None),
dict(s=R,t="Peace in the night",f="Psalm reflection + soft CTA",p=["For anyone who can't sleep tonight:\n\n\"{q}\"\n— Psalm 4:8\n\nYou can put it down. He's awake.\n\nPsalms in simple words, each with a short explanation: link in bio."],q=[("In peace I will lie down and sleep, for you alone, LORD, let me live in safety.","Psalmen:4:8")],img="a crescent moon in gold line art above a quiet house with one warm window"),
# Week 7 – identity & purpose
dict(s=P,t="Plans and steps",f="Hook + insight + life application",p=["You make the plan. Then life happens.\n\n\"{q}\"\n— Proverbs 16:9\n\nPlan anyway. Just hold it with open hands."],q=[("A person’s heart plans his way, but the LORD directs his steps.","Sprueche:16:9")],img="footprints in gold line art on a map, gently redirected by a guiding line of light"),
dict(s=S,t="Little David, chosen",f="Thread (mini-story retelling)",p=["1/ Before Goliath, there was a day nobody noticed David at all 🧵","2/ The prophet Samuel came to choose Israel's next king from Jesse's sons. The oldest looked perfect. Tall. Strong.\n\nGod said no.","3/ \"{q}\"\n— 1 Samuel 16:7","4/ David wasn't even invited. He was out with the sheep.\n\nThe world sees your profile. God sees your heart."],q=[("Man looks at the outward appearance, but the LORD looks at the heart.”","1-Samuel:16:7")],img="a young shepherd with a lamb on a hillside, a faint gold crown of light above him"),
dict(s=M,t="Wonderfully made",f="What this really means",p=["For anyone who hates the mirror today:\n\n\"{q}\"\n— Psalm 139:13–14\n\nYou are not a mistake or a draft. You were made with care, on purpose."],q=[("For you made the deepest parts of me. You wove me together inside my mother. I will thank you, for I am made in an amazing and wonderful way.","Psalmen:139:13-14")],img="gold line-art threads being woven into a human silhouette, stars around"),
dict(s=J,t="You are the light",f="Hook + insight + life application",p=["\"{q}\"\n— Matthew 5:14\n\nJesus didn't say ‘try to become light.’ He said you ARE.\n\nSo stop hiding it. Encourage someone today."],q=[("“You are the light of the world. A city that is built on a hill cannot be hidden.","Matthaeus:5:14")],img="a city on a hill glowing in gold line art against a midnight sky"),
dict(s=MT,t="Myth: You have to be perfect",f="Myth vs. truth",p=["Myth: God only uses perfect people.\n\nTruth: Moses stuttered. David failed badly. Peter denied Jesus 3 times.\n\nAnd Paul heard this:\n\"{q}\"\n— 2 Corinthians 12:9"],q=[("“My grace is sufficient for you, for my power is made perfect in weakness.”","2-Korinther:12:9")],img=None),
dict(s=Q,t="Your purpose in one word",f="Question to drive replies",p=["Colossians 3:23 says: whatever you do, do it from the heart.\n\nIf your life had a one-word purpose, what would it be?\n\nMine starts with: ‘encourage.’ Yours? 👇"],q=[],img=None),
dict(s=R,t="This is the day",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 118:24\n\nNot the day you wanted. Not the day you planned.\n\nThis one. Look for one good thing in it.\n\nRead the Bible in clear words, with explanations. Link in bio."],q=[("This is the day that the LORD has made. We will rejoice and be glad in it!","Psalmen:118:24")],img="a gold line sunrise over a city skyline, birds flying"),
# Week 8
dict(s=P,t="Commit your plans",f="Hook + insight + life application",p=["New project? New job? New start?\n\n\"{q}\"\n— Proverbs 16:3\n\nPray before you plan. Then work like it depends on you."],q=[("Commit your deeds to the LORD, and your plans will succeed.","Sprueche:16:3")],img=None),
dict(s=S,t="Esther: for such a time as this",f="Thread (mini-story retelling)",p=["1/ A young orphan becomes queen. Then she learns her people are about to be destroyed 🧵","2/ Speaking up could cost Esther her life. Her cousin Mordecai sends her a message:\n\n\"{q}\"\n— Esther 4:14","3/ She asks everyone to fast with her for three days. Then she walks into the king's room uninvited.","4/ She saves her people.\n\nMaybe you're exactly where you are for a reason. Maybe it's for a time like this."],q=[("Who knows? Maybe you have become queen for a time like this.”","Ester:4:14")],img="a young queen with a gold crown standing before an open palace door, gold line art"),
dict(s=M,t="Be transformed",f="What this really means",p=["\"{q}\"\n— Romans 12:2\n\nConformed = pressed into someone else's shape.\nTransformed = changed from the inside out.\n\nIt starts with what you let into your mind."],q=[("Don’t be conformed to this world, but be transformed by the renewing of your mind.","Roemer:12:2")],img="a caterpillar becoming a butterfly in gold line art"),
dict(s=J,t="Ask, seek, knock",f="Hook + insight + life application",p=["Three verbs. Three promises.\n\n\"{q}\"\n— Matthew 7:7\n\nThe door doesn't open because you stared at it."],q=[("“Ask, and it will be given to you. Seek, and you will find. Knock, and the door will be opened to you.","Matthaeus:7:7")],img="a hand knocking on a large old door outlined in gold, light leaking through the gap"),
dict(s=T,t="Big stories, simple lessons",f="Thread",p=["1/ 4 Bible stories, 4 life lessons. Under 60 seconds 🧵","2/ Jonah ran from God, ended up in a fish, and still got a second chance. → Running doesn't cancel grace.","3/ The widow gave two small coins and Jesus said she gave more than everyone. → Size isn't the point. Heart is.","4/ A boy gave 5 loaves and 2 fish. Thousands ate. → Bring what you have, even if it looks too small.\n\nWhich one hits home?"],q=[],img=None),
dict(s=Q,t="What would you ask God?",f="Question to drive replies",p=["If you could ask God one question and get a clear answer, what would it be?\n\nNo wrong answers. We read every reply 👇"],q=[],img=None),
dict(s=R,t="The path of life",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 16:11\n\nJoy isn't found at the end of the road. It's found walking with Him on it.\n\nThe whole Bible, plain and clear: link in bio."],q=[("You will show me the path of life. When I am with you, my joy is full.","Psalmen:16:11")],img="a winding gold path through mountains toward a glowing horizon"),
# Week 9 – hard times
dict(s=P,t="Fall seven times",f="Hook + insight + life application",p=["Failed again? Read this:\n\n\"{q}\"\n— Proverbs 24:16\n\nThe difference isn't that good people don't fall. It's that they get up.\n\nGet up."],q=[("For a righteous person falls seven times and gets up again","Sprueche:24:16")],img="a figure rising from the ground in gold line art, seven faint footprints behind"),
dict(s=S,t="Job: when everything is lost",f="Thread (mini-story retelling)",p=["1/ He lost his wealth, his health and his children in a short time. The book of Job in 60 seconds 🧵","2/ His first words are some of the hardest and most honest in the Bible:\n\n\"{q0}\"\n— Job 1:21","3/ Then come chapters of questions, tears and arguments. Job is honest with God. God doesn't scold him for it.","4/ \"{q1}\"\n— Job 42:10\n\nYou're allowed to ask why. God can handle your questions."],q=[("The LORD gave, and the LORD has taken away. May the name of the LORD be praised.”","Hiob:1:21"),("The LORD turned things around for Job when he prayed for his friends.","Hiob:42:10")],img="a man sitting on ashes under a vast starry sky, a gold line sunrise beginning on the horizon"),
dict(s=M,t="All things work together",f="What this really means",p=["\"{q}\"\n— Romans 8:28\n\nIt doesn't say all things ARE good. Some things are terrible.\n\nIt says God can weave even the terrible into something good. That's different. And deeper."],q=[("We know that all things work together for good for those who love God.","Roemer:8:28")],img="tangled gold threads turning into a beautiful woven pattern"),
dict(s=J,t="Jesus cried",f="Hook + insight + life application",p=["The shortest verse in the Bible:\n\n\"{q}\"\n— John 11:35\n\nHe knew Lazarus would live again in minutes. He cried anyway.\n\nGod doesn't rush your grief. He sits in it with you."],q=[("Jesus cried.","Johannes:11:35")],img="a single gold teardrop glowing against deep midnight blue"),
dict(s=MT,t="Myth: Christians shouldn't struggle",f="Myth vs. truth",p=["Myth: If you trust God, life gets easy.\n\nTruth:\n\"{q}\"\n— John 16:33\n\nTrouble is promised. So is His victory."],q=[("In the world you have trouble. But cheer up! I have overcome the world.”","Johannes:16:33")],img=None),
dict(s=Q,t="What helps you on bad days?",f="Question to drive replies",p=["Psalm 34:18: the LORD is near to those who have a broken heart.\n\nWhat helps YOU most on really hard days? A song, a person, a verse, a walk?\n\nShare it. It might help someone else 👇"],q=[],img=None),
dict(s=R,t="Near to the brokenhearted",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 34:18\n\nIf your heart is in pieces, you're not far from God. You're closer than you think.\n\nThe Psalms in plain words, with short explanations: link in bio."],q=[("The LORD is near to those who have a broken heart. He saves those whose spirit is crushed.","Psalmen:34:18")],img="a cracked gold heart with warm light shining through the cracks"),
# Week 10
dict(s=P,t="A heart at peace",f="Hook + insight + life application",p=["Comparison is a thief.\n\n\"{q}\"\n— Proverbs 14:30\n\nEnvy doesn't hurt the person you envy. It hurts you.\n\nCelebrate someone's win today."],q=[("A heart at peace is life for the body, but envy makes the bones rot.","Sprueche:14:30")],img=None),
dict(s=S,t="Elijah and the whisper",f="Thread (mini-story retelling)",p=["1/ The prophet Elijah was burned out. He ran into the desert and wanted to give up 🧵","2/ God told him to stand on a mountain. A storm came. An earthquake. A fire.\n\nBut God was in none of them.","3/ \"{q}\"\n— 1 Kings 19:12","4/ Sometimes God isn't in the loud thing. He's in the quiet.\n\nTurn the noise down today."],q=[("After the fire there was a still small voice.","1-Koenige:19:12")],img="a mountain with wind, earthquake cracks and fire in gold line art, a tiny gentle glow at the center"),
dict(s=M,t="Mercies new every morning",f="What this really means",p=["\"{q}\"\n— Lamentations 3:22–23\n\nWritten in the middle of a destroyed city.\n\nYesterday's mistakes don't carry over. God's mercy resets with the sunrise."],q=[("his mercies do not fail. They are new every morning. Great is your faithfulness.","Klagelieder:3:22-23")],img="a gold line sunrise over ruins with a small green sprout"),
dict(s=J,t="Peace! Be still!",f="Hook + insight + life application",p=["Storm. Waves crashing into the boat. The disciples are sure they'll die.\n\nJesus wakes up:\n\n\"{q}\"\n— Mark 4:39\n\nWhat storm do you need Him to speak to?"],q=[("“Peace! Be still!” Then the wind stopped, and there was a great calm.","Markus:4:39")],img="a small boat on a sea that becomes suddenly calm, gold line art, stars reflected"),
dict(s=T,t="Suffering → hope",f="Thread",p=["1/ Why does the Bible say to \"rejoice\" in suffering? That sounds crazy 🧵","2/ Paul explains the chain:\n\n\"{q}\"\n— Romans 5:3–4","3/ Not: pain is good.\nBut: pain can build something in you that comfort never could.","4/ Every strong person you admire has scars.\n\nYour hard season might be building your hope."],q=[("For we know that suffering produces perseverance. Perseverance produces proven character. And proven character produces hope.","Roemer:5:3-4")],img="a seed in dark soil growing into a tree of light, gold line art"),
dict(s=Q,t="Your hardest season",f="Question to drive replies",p=["Looking back, what did your hardest season teach you that nothing else could?\n\nOne sentence. 👇"],q=[],img=None),
dict(s=R,t="Hope in God",f="Psalm reflection + soft CTA",p=["Talking to yourself is biblical:\n\n\"{q}\"\n— Psalm 42:5\n\nTell your soul the truth today.\n\nEvery psalm explained in clear words: link in bio."],q=[("Why are you in such despair, my soul? Why are you so troubled inside me? Hope in God!","Psalmen:42:5")],img=None),
# Week 11 – forgiveness & grace
dict(s=P,t="Overlook a wrong",f="Hook + insight + life application",p=["Not every offense needs a response.\n\n\"{q}\"\n— Proverbs 19:11\n\nSome things you can just let go. That's not weakness. That's glory."],q=[("A person’s good sense makes him slow to anger. It is his glory to overlook a wrong.","Sprueche:19:11")],img=None),
dict(s=S,t="The son who came home",f="Thread (mini-story retelling)",p=["1/ A son demands his inheritance, leaves home and wastes everything. The most beautiful story Jesus told 🧵","2/ Broke and starving, he decides to go back and beg to be a servant.","3/ \"{q}\"\n— Luke 15:20","4/ The father RAN. In that culture, dignified older men didn't run.\n\nThat's how God feels when you come back."],q=[("He was still a long way off when his father saw him. His father felt deep love and pity for him. He ran to his son, threw his arms around his neck, and kissed him.","Lukas:15:20")],img="a father running with open arms toward a returning son on a road, gold line art, warm sunset light"),
dict(s=M,t="As far as east from west",f="What this really means",p=["\"{q}\"\n— Psalm 103:12\n\nNorth and south meet at the poles. East and west never meet.\n\nThat's how far your forgiven mistakes are from you. Stop digging them up."],q=[("As far as the east is from the west, so far has he removed our sins from us.","Psalmen:103:12")],img="a gold line compass with east and west arrows stretching endlessly"),
dict(s=J,t="Father, forgive them",f="Hook + insight + life application",p=["On the cross, in pain, Jesus prayed for the people hurting him:\n\n\"{q}\"\n— Luke 23:34\n\nIf He could forgive that, maybe we can forgive the person who hurt us."],q=[("“Father, forgive them. They don’t know what they are doing.”","Lukas:23:34")],img="a simple gold line cross on a hill under a dark sky with a soft glow"),
dict(s=MT,t="Myth: You have to earn it",f="Myth vs. truth",p=["Myth: God loves you if you're good enough.\n\nTruth:\n\"{q}\"\n— Ephesians 2:8\n\nA gift you earn is a paycheck. Grace is a gift."],q=[("For by grace you have been saved through faith. And that is not from yourselves. It is the gift of God.","Epheser:2:8")],img="a small gift box in gold line art, opened, light pouring out"),
dict(s=Q,t="Hardest thing to forgive",f="Question to drive replies",p=["Ephesians 4:32: be kind, tenderhearted, forgive one another.\n\nIs it harder for you to forgive others, or to forgive yourself?\n\nReply honestly. No judgment here."],q=[],img=None),
dict(s=R,t="A clean heart",f="Psalm reflection + soft CTA",p=["David wrote this after his worst mistake:\n\n\"{q}\"\n— Psalm 51:10\n\nNo excuses. Just a request for a new start. You can pray it too.\n\nThe Bible in plain words: link in bio."],q=[("Create in me a clean heart, O God. Make my spirit new and right again.","Psalmen:51:10")],img="a clear crystal heart in gold outline with soft light"),
# Week 12
dict(s=P,t="Pride before a fall",f="Hook + insight + life application",p=["\"{q}\"\n— Proverbs 16:18\n\nThe moment you think you can't fall is usually the moment before you do.\n\nStay humble. Stay teachable."],q=[("Pride goes before destruction, and a proud spirit before a fall.","Sprueche:16:18")],img=None),
dict(s=S,t="Zacchaeus up the tree",f="Thread (mini-story retelling)",p=["1/ The most hated man in town climbs a tree to see Jesus. What happens next surprises everyone 🧵","2/ Zacchaeus collected taxes and cheated people. He was also short, so he climbed a tree.","3/ \"{q}\"\n— Luke 19:5","4/ Jesus didn't wait for Zacchaeus to change. He came to his house first. Then Zacchaeus gave half his money to the poor.\n\nLove changes people more than shame ever could."],q=[("“Zacchaeus, hurry and come down! Today I must stay at your house.”","Lukas:19:5")],img="a man sitting in a sycamore tree looking down at a figure of light, gold line art"),
dict(s=M,t="70 times 7",f="What this really means",p=["Peter thought 7 times was generous. Jesus said 70 × 7.\n\nNot because you should count to 490.\n\nBecause if you're counting, you haven't really forgiven yet."],q=[],img="the numbers 70 × 7 in elegant gold serif, dissolving into stars"),
dict(s=J,t="Love each other",f="Hook + insight + life application",p=["How will people know you follow Jesus? Not by your T-shirt.\n\n\"{q}\"\n— John 13:35"],q=[("If you love each other, then everyone will know that you are my disciples.”","Johannes:13:35")],img=None),
dict(s=T,t="The lost sheep, coin and son",f="Thread",p=["1/ In Luke 15, Jesus tells 3 stories in a row. Same point each time 🧵","2/ A shepherd with 100 sheep loses one.\n\n\"{q}\"\n— Luke 15:4","3/ A woman loses a coin and sweeps the whole house. A father loses a son and runs to meet him.","4/ All three end with a party.\n\nYou're not a number to God. You're the one He goes looking for."],q=[("Won’t he leave the 99 sheep in the wilderness? Won’t he go and look for the lost sheep until he finds it?","Lukas:15:4")],img="a shepherd carrying a lamb on his shoulders, gold line art, 99 small sheep in the distance"),
dict(s=Q,t="Grace in one sentence",f="Question to drive replies",p=["Explain \"grace\" to a 12-year-old in one sentence.\n\nGo 👇"],q=[],img=None),
dict(s=R,t="Rest in God alone",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 62:1\n\nNot in likes. Not in success. Not in people's approval.\n\nRest there today.\n\nEvery verse in clear words, with short explanations: link in bio."],q=[("My soul finds rest in God alone. My rescue comes from him.","Psalmen:62:1")],img="a single gold line-art bench under a large tree at dusk"),
# Week 13 – hope
dict(s=P,t="Brighter and brighter",f="Hook + insight + life application",p=["Growth is slow. Then it isn't.\n\n\"{q}\"\n— Proverbs 4:18\n\nYou don't have to be at noon yet. Dawn counts."],q=[("But the path of the righteous is like the light of dawn that shines brighter and brighter until the full day.","Sprueche:4:18")],img="a path that grows from faint to bright gold as it reaches the horizon"),
dict(s=S,t="Daniel in the lions' den",f="Thread (mini-story retelling)",p=["1/ A law says: pray to anyone but the king and you go to the lions. Daniel keeps praying anyway 🧵","2/ Three times a day, windows open. He's caught and thrown into the den.","3/ Next morning the king runs to the den. Daniel calls out:\n\n\"{q}\"\n— Daniel 6:22","4/ Daniel didn't change who he was to stay safe.\n\nIntegrity when no one is watching is integrity when everyone is."],q=[("My God has sent his angel, and he has shut the lions’ mouths.","Daniel:6:22")],img="a calm man standing among resting lions in gold line art, a beam of light from above"),
dict(s=M,t="Wings like eagles",f="What this really means",p=["\"{q}\"\n— Isaiah 40:31\n\nWaiting in the Bible isn't sitting around. It's trusting while you keep going.\n\nRun. Walk. Rise. Each season has its speed."],q=[("But those who wait for the LORD will renew their strength. They will rise up on wings like eagles.","Jesaja:40:31")],img="an eagle in gold line art soaring over mountains at sunrise"),
dict(s=J,t="He is risen",f="Hook + insight + life application",p=["The most important sentence in Christian history:\n\n\"{q}\"\n— Matthew 28:6\n\nAn empty tomb means death doesn't get the last word. Neither does your worst day."],q=[("He is not here. For he has risen, just as he said.","Matthaeus:28:6")],img="an empty tomb with the stone rolled away, gold light streaming out at dawn"),
dict(s=MT,t="Myth: Faith = blind",f="Myth vs. truth",p=["Myth: Faith means believing without any reason.\n\nTruth:\n\"{q}\"\n— 1 Peter 3:15\n\nFaith asks questions. It looks for answers. And it shares them kindly."],q=[("Always be ready to give an answer to everyone who asks you the reason for the hope that is in you.","1-Petrus:3:15")],img=None),
dict(s=Q,t="What gives you hope?",f="Question to drive replies",p=["Hebrews 11:1: faith is assurance of things hoped for.\n\nWhat are you hoping for right now? Say it out loud (well, type it) 👇"],q=[],img=None),
dict(s=R,t="Lift up your eyes",f="Psalm reflection + soft CTA",p=["\"{q}\"\n— Psalm 121:1–2\n\nLook up from the screen for a second. The One who made everything knows your name.\n\nThe Bible in plain words, every verse: link in bio."],q=[("I lift up my eyes to the hills. Where does my help come from? My help comes from the LORD, who made heaven and earth.","Psalmen:121:1-2")],img="hills under a vast starry sky drawn in gold line art, a figure looking up"),
# Week 14 – wrap-up arc
dict(s=P,t="Do good when you can",f="Hook + insight + life application",p=["\"{q}\"\n— Proverbs 3:27\n\nThe text you've been meaning to send. The help you've been meaning to offer.\n\nDo it today."],q=[("Do good to those who need it. Don’t hold it back when you are able to do it.","Sprueche:3:27")],img=None),
dict(s=S,t="Five loaves, two fish",f="Thread (mini-story retelling)",p=["1/ Thousands of hungry people. No food. And one boy with a small lunch 🧵","2/ \"{q}\"\n— John 6:9","3/ Jesus takes the bread, gives thanks, and shares it. Everyone eats until they're full. Twelve baskets are left over.","4/ Your little might be someone's miracle.\n\nWhat can you offer, even if it seems small?"],q=[("“There is a boy here who has five barley loaves and two fish. But what is that for so many people?”","Johannes:6:9")],img="five loaves and two fish in gold line art inside a small basket, glowing"),
dict(s=M,t="Faith, hope and love",f="What this really means",p=["\"{q}\"\n— 1 Corinthians 13:13\n\nOne day faith becomes sight. Hope becomes reality.\n\nLove is the only one that lasts forever. Invest there."],q=[("So now these three remain: faith, hope and love. The greatest of these is love.","1-Korinther:13:13")],img="three gold line icons: a cross, an anchor and a heart, side by side"),
dict(s=J,t="Mary and Martha",f="Hook + insight + life application",p=["Martha was busy serving. Mary sat and listened. Martha complained. Jesus said:\n\n\"{q}\"\n— Luke 10:41–42\n\nBusy isn't the same as important."],q=[("“Martha, Martha, you are worried and upset about many things. But only one thing is needed.","Lukas:10:41-42")],img=None),
dict(s=T,t="100 days: what we learned",f="Thread",p=["1/ We're almost at 100 days of daily Bible posts. 4 things this journey showed us 🧵","2/ You love the stories. David, Ruth, Joseph, Esther: real people with real problems.","3/ Anxiety and fear are the #1 topics you ask about. That's why we keep coming back to verses like 1 Peter 5:7.","4/ Plain words help. When the Bible is clear, people read it.\n\nThank you for reading along. More soon."],q=[],img=None),
dict(s=P,t="Stop waiting for perfect",f="Hook + insight + life application",p=["Waiting for the perfect moment to start?\n\n\"{q}\"\n— Ecclesiastes 11:4\n\nThe conditions will never be perfect. Sow anyway."],q=[("Whoever watches the wind will not sow, and whoever looks at the clouds will not harvest.","Prediger:11:4")],img="a farmer scattering seeds in gold line art while clouds drift overhead"),
dict(s=S,t="Jonah: the runaway prophet",f="Thread (mini-story retelling)",p=["1/ God says ‘go east.’ Jonah buys a ticket west. The story of Jonah in 60 seconds 🧵","2/ \"{q0}\"\n— Jonah 1:3","3/ A storm, a big fish, three days in the dark. Jonah prays and gets a second chance. He finally goes to Nineveh, and the city turns around.","4/ Jonah is angry that God was kind to his enemies. God answers with a question about caring for 120,000 people.\n\nGod's mercy is bigger than our grudges."],q=[("But Jonah got up to run away to Tarshish, away from the LORD.","Jona:1:3")],img="a large fish beneath a small boat on stormy waves, gold line art on midnight blue"),
dict(s=Q,t="What should we cover next?",f="Question to drive replies",p=["Which book or story of the Bible should we explain next?\n\nMost-requested gets its own series 👇"],q=[],img=None),
dict(s=R,t="Day 100: No more tears",f="Reflection + soft CTA",p=["Day 100. The Bible ends with this promise:\n\n\"{q}\"\n— Revelation 21:4\n\nThank you for reading with us. The Bible in clear words: link in bio."],q=[("He will wipe away every tear from their eyes. There will be no more death. There will be no more grief, no more crying, and no more pain.","Offenbarung:21:4")],img="a new dawn over a peaceful city of light, gold line art on deep midnight blue, warm glow"),
]
